parameters.jsCode:
const mails = $('Read unread email (IMAP)').all();
const CATS = ['sales lead', 'support', 'invoice/billing', 'spam', 'other'];
return $input.all().map((item, i) => {
  let ai = {};
  try { ai = JSON.parse(item.json.choices[0].message.content); } catch (e) {}
  const m = mails[i].json;
  const category = CATS.includes(String(ai.category).toLowerCase()) ? String(ai.category).toLowerCase() : 'other';
  const urgency = ['high', 'medium', 'low'].includes(String(ai.urgency).toLowerCase()) ? String(ai.urgency).toLowerCase() : 'medium';
  return { json: {
    date: m.date, from: m.from, subject: m.subject, category, urgency,
    name: ai.name || '', company: ai.company || '', request: ai.request || '', summary: ai.summary || '',
    'draft reply (not sent)': category === 'spam' ? '' : (ai.reply || ''),
  } };
});
